def icon(name):
 return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+PATHS.get(name,PATHS['file'])+'"/></svg>'

CSS='''<style>
:root{--bg:#f3f6fa;--surface:#fff;--text:#203047;--muted:#778397;--border:#e4eaf1;--accent:#087f80;--soft:#e8f6f3;--nav:#132a3b;--shadow:0 4px 18px #162d4710;color-scheme:light}
:root[data-theme=dark]{--bg:#101a25;--surface:#192736;--text:#edf2f8;--muted:#a7b5c6;--border:#304254;--accent:#68d6c2;--soft:#233f42;--nav:#0c1722;--shadow:none;color-scheme:dark}
*{box-sizing:border-box}body{font-family:Tahoma,"Segoe UI",Arial,sans-serif;background:var(--bg);color:var(--text);margin:0;font-size:14px;line-height:1.65}a{color:var(--accent)}button,input,select,textarea{font:inherit}button,a,input,select,summary{outline-offset:4px}button{cursor:pointer;background:#087f80;color:white;border:0;border-radius:9px;padding:10px 17px;font-weight:600}button:hover{filter:brightness(.95)}button:disabled{opacity:.5;cursor:not-allowed}input,select,textarea{border:1px solid var(--border);background:var(--surface);color:var(--text);border-radius:8px;padding:9px 11px;min-height:40px;max-width:100%}input:focus,select:focus{outline:2px solid #3aada477}input[type=file]{max-width:100%;width:320px}input[type=number]{direction:ltr;text-align:right}form{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}form label{font-size:12px;color:var(--muted)}form label input,form label select{display:block;margin-top:5px;color:var(--text)}h1{font-size:26px;line-height:1.5;margin:0 0 8px;letter-spacing:-.5px}h2{font-size:18px;margin:0 0 12px;line-height:1.6}h3{font-size:15px;margin:0 0 10px}p{margin:10px 0}.muted{color:var(--muted)}.ok{color:#118a68}.warn{color:#d7504a}
.app-sidebar{position:fixed;inset:0 0 0 auto;width:256px;background:var(--nav);color:#d5e1eb;z-index:40;display:flex;flex-direction:column;flex-wrap:nowrap!important;overflow:hidden;padding:0!important;gap:0!important}
.brand{display:flex;align-items:center;gap:12px;padding:24px 20px 18px;border-bottom:1px solid #ffffff10}.brand-mark{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:#118c88;color:white;font-size:26px;font-weight:bold}.brand-mark svg{width:36px;height:36px}.brand b{display:block;color:white;font-size:16px}.brand small{color:#92abbc;font-size:11px}.nav-search{margin:16px 16px 8px;width:calc(100% - 32px);min-width:0;background:#ffffff09!important;border-color:#ffffff19!important;color:white!important;font-size:12px}.nav-search::placeholder{color:#8ca5b7}.nav-scroll{overflow-y:auto;overflow-x:hidden;flex:1;padding:8px 12px 20px;scrollbar-width:thin;scrollbar-color:#426074 transparent}.nav-group{margin:8px 0}.nav-group summary{cursor:pointer;list-style:none;color:#92abbc;font-size:11px;letter-spacing:.3px;padding:10px 12px;display:flex;justify-content:space-between}.nav-group summary:after{content:'+';font-size:14px}.nav-group[open] summary:after{content:'−'}.nav-group summary::-webkit-details-marker{display:none}.nav-link{display:flex!important;align-items:center;gap:11px;padding:10px 12px!important;margin:3px 0;border-radius:8px;color:#c9d8e4!important;text-decoration:none;font-size:13px;line-height:1.5;white-space:normal;min-width:0}.nav-link svg{width:18px;height:18px;flex:none;color:#8da9bc}.nav-link:hover{background:#ffffff09!important}.nav-link.active{background:#137f782d!important;color:#83e6d7!important;box-shadow:inset -3px 0 #38c6ae}.nav-link.active svg{color:#83e6d7}.nav-footer{padding:12px 20px;border-top:1px solid #ffffff12;display:flex;align-items:center;justify-content:space-between;font-size:11px;color:#8ca5b7}.nav-footer a{color:#b8cddc;text-decoration:none}.app-main{margin-right:256px;min-width:0;min-height:100vh}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 32px;background:var(--surface);border-bottom:1px solid var(--border)}.breadcrumb{font-size:12px;color:var(--muted)}.breadcrumb b{color:var(--text);font-weight:500}.top-actions{display:flex;align-items:center;gap:12px}.top-actions time{font-size:12px;color:var(--muted)}.icon-btn{background:var(--surface);color:var(--text);border:1px solid var(--border);padding:7px 11px;min-height:36px}.menu-btn{display:none}.wrap{max-width:1560px;padding:28px 32px 40px;margin:0 auto}.page-heading{margin-bottom:24px}.eyebrow{font-size:11px;color:var(--accent);font-weight:bold;margin-bottom:5px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:16px;min-width:0}.card{background:var(--surface);border:1px solid var(--border);border-radius:13px;padding:20px;box-shadow:var(--shadow);min-width:0}.kpi{font-size:28px;font-weight:700;direction:ltr;text-align:right;line-height:1.5;margin-top:6px;font-variant-numeric:tabular-nums}.action{display:inline-flex;align-items:center;gap:8px;text-decoration:none;border:1px solid var(--border);border-radius:8px;padding:8px 13px;background:var(--surface);font-size:12px;margin:3px}.action.primary{color:white;background:#087f80;border-color:#087f80}.table-scroll{overflow-x:auto;border:1px solid var(--border);border-radius:12px;background:var(--surface);max-width:100%;margin-top:12px}table{width:100%;border-collapse:collapse;background:var(--surface);font-size:12px}th,td{padding:13px 14px;border-bottom:1px solid var(--border);text-align:right;vertical-align:middle;white-space:nowrap}th{font-size:11px;color:var(--muted);font-weight:600;background:var(--bg)}tbody tr:last-child td{border-bottom:0}tbody tr:hover{background:var(--soft)}td code{font-size:11px}.table-scroll table{margin:0}.module-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.module{display:flex;align-items:center;gap:14px;text-decoration:none;color:var(--text);padding:18px;min-height:98px;transition:border-color .15s,transform .15s}.module:hover{border-color:#56b6a6;transform:translateY(-2px)}.module-icon{display:grid;place-items:center;width:43px;height:43px;flex:none;border-radius:12px;background:var(--soft);color:var(--accent)}.module-icon svg{width:22px;height:22px}.module h2{font-size:14px;margin:0 0 4px}.module small{font-size:11px;color:var(--muted)}.module-arrow{margin-right:auto;color:var(--muted)}.dashboard-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:22px}.dashboard-head p{margin:0}.section-title{display:flex;justify-content:space-between;align-items:center;margin:26px 0 13px}.section-title h2{margin:0;font-size:16px}.section-title span{font-size:11px;color:var(--muted)}.metric{position:relative;padding:19px 20px}.metric .metric-label{font-size:12px;color:var(--muted)}.metric small{color:var(--muted);font-size:10px}.metric:before{content:'';position:absolute;top:20px;left:20px;width:7px;height:7px;border-radius:50%;background:#24a99a}.dashboard-lower{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:24px}.dashboard-lower .card{box-shadow:none}.step-row{display:flex;gap:12px;padding:13px 0;border-bottom:1px solid var(--border)}.step-row:last-child{border-bottom:0}.step-number{width:26px;height:26px;flex:none;border-radius:8px;background:var(--soft);color:var(--accent);display:grid;place-items:center;font-size:11px}.step-row b{display:block;font-size:12px}.step-row p{font-size:11px;color:var(--muted);margin:4px 0 0}.empty-state{text-align:center;padding:35px 15px;color:var(--muted)}.pill{display:inline-block;border-radius:20px;background:var(--soft);color:var(--accent);padding:3px 9px;font-size:10px}.overlay{display:none}.app-sidebar [hidden]{display:none!important}.login-shell .wrap{max-width:480px;margin:8vh auto}
@media(min-width:1600px){.module-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:1200px){.app-sidebar{width:230px}.app-main{margin-right:230px}.wrap{padding:24px}.topbar{padding:0 24px}.module-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.dashboard-lower{grid-template-columns:1fr}.top-actions time{display:none}}
@media(max-width:900px){.app-sidebar{width:256px;transform:translateX(100%);transition:transform .2s}.app-main{margin-right:0}.menu-btn{display:block}.sidebar-open .app-sidebar{transform:translateX(0)}.sidebar-open .overlay{display:block;position:fixed;inset:0;background:#08162288;z-index:35;border:0;border-radius:0}.topbar{height:62px;padding:0 18px}.wrap{padding:22px 18px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.page-heading{margin-bottom:18px}h1{font-size:23px}}
@media(max-width:540px){.module-grid{grid-template-columns:1fr}.grid{gap:10px}.card{padding:16px}.kpi{font-size:23px}.dashboard-head{align-items:flex-start;flex-direction:column}.breadcrumb{font-size:11px}.top-actions{gap:6px}.topbar{gap:8px}.wrap{padding:18px 12px}form{align-items:stretch}form input:not([type=number]),form select{max-width:100%}.dashboard-lower{margin-top:18px}.pos-grid{display:block!important}.pos-grid>section{margin-bottom:14px}}
@media print{.app-sidebar,.topbar,.overlay,.no-print,form,button{display:none!important}.app-main{margin:0}.wrap{max-width:none;padding:0}.page-heading{margin:0 0 12px}body{background:white;color:black;font-size:11px}.card{box-shadow:none;border:1px solid #ddd}.table-scroll{overflow:visible;border:0}table{font-size:9px}th,td{padding:5px;white-space:normal;border-color:#ccc}thead{display:table-header-group}tr{break-inside:avoid}.grid{grid-template-columns:repeat(4,1fr)}.kpi{font-size:18px}}
</style>'''

SCRIPT='''<script>
(()=>{const body=document.body,menu=document.getElementById('menu-button'),overlay=document.getElementById('nav-overlay');function close(){body.classList.remove('sidebar-open');menu.setAttribute('aria-expanded','false')}
menu.onclick=()=>{const open=body.classList.toggle('sidebar-open');menu.setAttribute('aria-expanded',String(open))};overlay.onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
const path=location.pathname;document.querySelectorAll('.nav-link').forEach(a=>{if(a.getAttribute('href')===path||(a.getAttribute('href')!=='/'&&path.startsWith(a.getAttribute('href')+'/'))){a.classList.add('active');a.setAttribute('aria-current','page');a.closest('details').open=true}});
document.querySelectorAll('.nav-group').forEach(g=>{try{const state=localStorage.getItem('pharm-nav-'+g.dataset.group);if(state!==null&&!g.querySelector('.active'))g.open=state==='1'}catch{}g.addEventListener('toggle',()=>{try{localStorage.setItem('pharm-nav-'+g.dataset.group,g.open?'1':'0')}catch{}})});
document.getElementById('nav-search').oninput=e=>{const q=e.target.value.trim();document.querySelectorAll('.nav-group').forEach(g=>{let visible=0;g.querySelectorAll('a').forEach(a=>{a.hidden=!a.textContent.includes(q);if(!a.hidden)visible++});g.hidden=!visible;if(q)g.open=true})};
const theme=document.getElementById('theme-button');function label(){theme.textContent=document.documentElement.dataset.theme==='dark'?'وضع فاتح':'وضع داكن'}label();theme.onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('pharm-theme',document.documentElement.dataset.theme)}catch{}label()};
document.querySelectorAll('main table').forEach(t=>{if(!t.parentElement.classList.contains('table-scroll')&&!t.parentElement.classList.contains('scroll')){const wrap=document.createElement('div');wrap.className='table-scroll';t.before(wrap);wrap.append(t)}});
const date=document.getElementById('today-label');date.textContent=new Intl.DateTimeFormat('ar-EG',{dateStyle:'medium'}).format(new Date());
})();</script>'''

def render_page(title,body):
 from fastapi.responses import HTMLResponse
 nav=''
 for i,(name,links) in enumerate(GROUPS):
  nav+=f'<details class="nav-group" data-group="{i}" {"open" if i==0 else ""}><summary>{name}</summary>'
  nav+=''.join(f'<a class="nav-link" href="{url}">{icon(symbol)}<span>{name}</span></a>' for url,name,symbol in links)+'</details>'
 return HTMLResponse(f'''<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | eg4hosting pharmacy POS</title><script>try{{document.documentElement.dataset.theme=localStorage.getItem('pharm-theme')||'light'}}catch{{}}</script>{CSS}</head><body><aside class="app-sidebar" id="app-navigation" aria-label="القائمة الرئيسية"><div class="brand"><span class="brand-mark">{LOGO_SVG}</span><div><b>eg4hosting</b><small>pharmacy POS</small><small>إدارة الصيدلية · v1.2.0</small></div></div><input id="nav-search" class="nav-search" aria-label="البحث في القائمة" placeholder="ابحث في القائمة…"><div class="nav-scroll">{nav}</div><div class="nav-footer"><span>نسخة تجريبية</span><a href="/logout">تسجيل الخروج ←</a></div></aside><button id="nav-overlay" class="overlay" aria-label="إغلاق القائمة" tabindex="-1"></button><div class="app-main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button id="menu-button" class="icon-btn menu-btn" aria-label="فتح القائمة" aria-controls="app-navigation" aria-expanded="false">☰</button><div class="breadcrumb">الصيدلية &nbsp; / &nbsp; <b>{escape(title)}</b></div></div><div class="top-actions"><time id="today-label"></time><button id="theme-button" class="icon-btn">وضع داكن</button></div></header><main class="wrap"><div class="page-heading"><div class="eyebrow">مساحة العمل</div><h1>{escape(title)}</h1></div>{body}</main></div>{SCRIPT}</body></html>''')
